    if (nt !== '' || (none && blank === 'noteThreshold')) body.noteThreshold = nt;
    if (gd !== '' || (none && blank === 'graceDays')) body.graceDays = gd;
    if (ed !== '' || (none && blank === 'entryDate')) body.entryDate = ed;
    for (const action of PERM_ACTIONS) {
